E=20
H=30
TRAINED_EPOCHS=40
MODEL_ID=1282619148

from ti_system import store_list,recall_list
ALPHABET="0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz!#$%&()*+-;<=>?@^_`{|}~"

# After installation, rerunning tinydata is the visible-shell paste helper.
# A ti_draw canvas cannot expose input() before the graphics program finishes.
try:
    installed=recall_list("tdinfo")
except Exception:
    installed=[]
if len(installed)>7 and int(installed[0])==13 and int(installed[7])==MODEL_ID:
    pasted=input("Paste for CalcGPT, then press Enter: ")
    store_list("tdpaste",[ord(ch) for ch in pasted[:120]])
    print("Paste saved. Run CalcGPT.")
    raise SystemExit

def decode_raw(parts,length):
    blob="".join(parts); out=[]
    for start in range(0,len(blob),5):
        value=0
        for ch in blob[start:start+5]: value=value*85+ALPHABET.index(ch)
        out.extend(((value>>24)&255,(value>>16)&255,(value>>8)&255,value&255))
    return out[:length]

def save_chunks(prefix,data,size=800):
    count=(len(data)+size-1)//size
    for part in range(count):
        store_list(prefix+str(part),data[part*size:(part+1)*size])
        print("Installing",prefix,part+1,"of",count)
    return count

print("Installing TinyLM model data into this TI-Nspire problem...")
qparts=[]
for i in range(len(PACKED)):
    values=decode_raw(PACKED[i],LENS[i])
    for j in range(len(values)):
        if values[j]>127: values[j]-=256
    pairs=[]
    for j in range(0,len(values),2):
        first=values[j]+128
        second=values[j+1]+128 if j+1<len(values) else 128
        pairs.append(first*256+second)
    qparts.append(save_chunks("tdq"+str(i)+"x",pairs))
chars=[]
for word in VOCAB:
    for ch in word: chars.append(ord(ch))
    chars.append(0)
vparts=save_chunks("tdvc",chars)
assoc=decode_raw(ASSOC_PACKED,ASSOC_LENGTH)
aparts=save_chunks("tda",assoc)
store_list("tdlens",list(LENS))
store_list("tdscale",list(S))
store_list("tdqp",qparts)
store_list("tdinfo",[13,E,H,TRAINED_EPOCHS,len(VOCAB),vparts,aparts,MODEL_ID])
print("TinyLM data installed. You can now run tinylm.")
